install:
sed -i '/case \$- in/,/esac/d' ~/.bashrc 2>/dev/null || true; if [ -d /usr/lib/jvm/java-21-openjdk-amd64 ]; then grep -qxF 'export GRADLE_OPTS="-Dorg.gradle.java.home=/usr/lib/jvm/java-21-openjdk-amd64"' ~/.bashrc || echo 'export GRADLE_OPTS="-Dorg.gradle.java.home=/usr/lib/jvm/java-21-openjdk-amd64"' >> ~/.bashrc; export GRADLE_OPTS='-Dorg.gradle.java.home=/usr/lib/jvm/java-21-openjdk-amd64'; fi; mkdir -p ~/.gradle/init.d && printf 'allprojects {
    pluginManager.withPlugin("com.android.application") {
        if (layout.buildDirectory.get().asFile.path.contains("C:")) {
            layout.buildDirectory.set(file("/home/antigravity/.gradle_builds/" + rootProject.name + "/" + project.name))
        }
    }
    afterEvaluate {
        if (layout.buildDirectory.get().asFile.path.contains("C:")) {
            layout.buildDirectory.set(file("/home/antigravity/.gradle_builds/" + rootProject.name + "/" + project.name))
        }
    }
}
' > ~/.gradle/init.d/linux-build-dir.gradle.kts; bash ./gradlew --version --no-daemon
